  g.fill((x, y) => (x > 2 && x < 5 && y > 2 && y < 5 ? TEAL : undefined), f.nx);
  g.fill((x, y) => (y === 3 && x > 1 && x < 6 ? TEAL : undefined), f.nz);
});

