329:export default function build() {
330:  const b = createBuilder({ name: "monsterTruck", paintSize: 2048 });
331:
332:  // ---- skeleton ------------------------------------------------------------------------------------------
333:  const chassis = b.joint("chassis", { at: [0, 1.2, 0] });
334:  const axleF = b.joint("axleF", { parent: chassis, at: [0, 0.85, 1.5], dir: [0, 1, 0], role: "hinge" });
335:  const axleR = b.joint("axleR", { parent: chassis, at: [0, 0.85, -1.5], dir: [0, 1, 0], role: "hinge" });
336:  const steer: Record<number, Joint> = {};
337:  const wheelJ: Record<string, Joint> = {};
338:  for (const s of [1, -1]) {
339:    const side = s > 0 ? "L" : "R";
340:    steer[s] = b.joint(`steerF${side}`, { parent: axleF, at: [s * 1.1, 0.85, 1.5], dir: [0, 1, 0], role: "hinge" });
341:    wheelJ[`F${s}`] = b.joint(`wheelF${side}`, { parent: steer[s], at: [s * 1.5, 0.85, 1.5], dir: [s, 0, 0], role: "hinge" });
342:    wheelJ[`R${s}`] = b.joint(`wheelR${side}`, { parent: axleR, at: [s * 1.5, 0.85, -1.5], dir: [s, 0, 0], role: "hinge" });
343:  }
344:  const doorJ: Record<number, Joint> = {};
345:  for (const s of [1, -1])
346:    doorJ[s] = b.joint(`door${s > 0 ? "L" : "R"}`, { parent: chassis, at: [s * 0.9, 1.6, 0.9], dir: [0, 1, 0], role: "hinge" });
347:  const hood = b.joint("hood", { parent: chassis, at: [0, 2.16, 1.0], dir: [0, 0, 1], role: "hinge" });
348:  const tailgate = b.joint("tailgate", { parent: chassis, at: [0, 1.76, -2.55], dir: [0, 0, -1], role: "hinge" });
349:  const wheelSteer = b.joint("steeringWheel", { parent: chassis, at: [0.42, 2.3, 0.32], dir: [0, 0.5, -0.86], role: "hinge" });
350:
351:  // ---- merge bags: many small static pieces become one part per bone and colour -------------------------
352:  const bags = new Map<string, { bone: Joint; color: Col; geos: THREE.BufferGeometry[] }>();
353:  const add = (bone: Joint, color: Col, g: THREE.BufferGeometry) => {
354:    const key = `${bone.name}|${String(color)}`;
355:    let e = bags.get(key);
356:    if (!e) bags.set(key, (e = { bone, color, geos: [] }));
357:    e.geos.push(g);
358:  };
359:  const place = (g: THREE.BufferGeometry, pos: V, rot?: V) => {
360:    if (rot) g.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(rot[0] * D, rot[1] * D, rot[2] * D)));
361:    return g.translate(pos[0], pos[1], pos[2]);
362:  };
363:  const box = (bone: Joint, color: Col, size: V, pos: V, rot?: V) =>
364:    add(bone, color, place(new THREE.BoxGeometry(size[0], size[1], size[2]), pos, rot));
365:  const cyl = (bone: Joint, color: Col, rTop: number, rBot: number, h: number, pos: V, axis: "x" | "y" | "z", seg = 8) => {
366:    const g = new THREE.CylinderGeometry(rTop, rBot, h, seg);
367:    if (axis === "x") g.rotateZ(-Math.PI / 2);
368:    if (axis === "z") g.rotateX(Math.PI / 2);
369:    add(bone, color, place(g, pos));
370:  };
371:  const tube = (bone: Joint, color: Col, a: V, c: V, r: number, seg = 6) => {
372:    const A = new THREE.Vector3(...a);
373:    const C = new THREE.Vector3(...c);
374:    const dir = C.clone().sub(A);
375:    const g = new THREE.CylinderGeometry(r, r, dir.length(), seg);
